create table public.agenda_editorial (
 id bigint generated always as identity primary key,
 titulo text not null, categoria text not null, lugar text not null, horario text not null,
 descripcion text not null, imagen text not null, fuente text not null check (fuente ~ '^https://'),
 etiqueta text not null, desde date not null, hasta date not null check(hasta >= desde), dias date[] not null,
 publicada boolean not null default false
);
alter table public.agenda_editorial enable row level security;
revoke all on public.agenda_editorial from public, anon, authenticated;
grant select on public.agenda_editorial to anon, authenticated;
grant insert,update on public.agenda_editorial to authenticated;
create policy lectura_agenda on public.agenda_editorial for select using (publicada);
create policy lectura_admin_agenda on public.agenda_editorial for select to authenticated using ((select public.es_admin()));
create policy alta_agenda on public.agenda_editorial for insert to authenticated with check ((select public.es_admin()));
create policy edicion_agenda on public.agenda_editorial for update to authenticated using ((select public.es_admin())) with check ((select public.es_admin()));
